//상장신청제한
/**
 * @method
 * @name onLoadPage
 * @description desc
 * @param {string} reject_cd desc
 * @param {string} flag desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.onLoadPage = function(reject_cd, flag) {
    if (reject_cd == 'Y' && flag != 'VIEW') {
        document.location = '../jsp/BB_VW004.jsp';
    }
};



/********************************* 팝업창 시작 ***********************************************/
//수수료
/**
 * @method
 * @name PopUp_FeeCal
 * @description desc
 * @param {string} fm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.PopUp_FeeCal = function(fm) {
    var fm = document.SendForm;
    if (GetByte(fm.appl_isu_nm.getValue()) == 0) {
        alert("한글종목명을 입력해주십시오.");
        fm.appl_isu_nm.focus();
        return;
    }
    if (GetByte(fm.isu_amt.getValue()) == 0) {
        alert("발행금액을 입력해주십시오.");
        fm.isu_amt.focus();
        return;
    }
    if (GetByte(fm.list_amt.getValue()) == 0) {
        alert("상장금액을 입력해주십시오.");
        fm.list_amt.focus();
        return;
    }
    if (GetByte(fm.isu_dd.getValue()) == 0) {
        alert("발행일을 입력해주십시오.");
        fm.isu_dd.focus();
        return;
    }
    if (GetByte(fm.procs_req_dd.getValue()) == 0) {
        alert("상장희망일을 입력해주십시오.");
        fm.procs_req_dd.focus();
        return;
    }
    if (scwin.fnToday() >= fm.procs_req_dd.getValue().replace("-", "").replace("-", "")) {
        alert("상장희망일은 신청일 익일 이후만 입력가능합니다.");
        fm.procs_req_dd.focus();
        return;
    }
    if (GetByte(fm.redmpt_dd.getValue()) == 0) {
        alert("상환일을 입력해주십시오.");
        fm.redmpt_dd.focus();
        return;
    }
    if (!fm.curr_tp_cd[0].checked && !fm.curr_tp_cd[1].checked && !fm.curr_tp_cd[2].checked && !fm.curr_tp_cd[3].checked && !fm.curr_tp_cd[4].checked) {
        alert("발행통화를 선택해주십시오.");
        fm.curr_tp_cd[0].focus();
        return;
    }
    var width = 690;
    var height = 780;
    var mtWidth = document.body.clientWidth;
    var mtHeight = document.body.clientHeight;
    var scX = window.screenLeft;
    var scY = window.screenTop;
    var popX = scX + (mtWidth - width) / 2;
    var popY = scY + (mtHeight - height) / 2;
    var _previewWindow;
    _previewWindow = window.open('', 'feeSearch', 'WIDTH=' + width + ',HEIGHT=' + height + ',TOP=' + popY + ',LEFT=' + popX + ',resizable=no,status=yes,scrollbars=yes');
    _previewWindow.opener = self;
    fm.action = '/main/fee.do';
    fm.method.setValue('feeSearchView');
    //fm.action='/common/AmtSearch.do?method=amtSearchView';
    fm.target = 'feeSearch';
    fm.submit();
};


//주식관련
/**
 * @method
 * @name PopUp_stk_rltn_bnd_cd
 * @description desc
 * @param {string} fm desc
 * @param {string} div desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.PopUp_stk_rltn_bnd_cd = function(fm, div) {
    var fm = document.SendForm;

    //특이채권유형 일반채권 
    if (fm.nusual_bnd_tp_cd[0].checked) {
        if (fm.stk_save_yn.getValue() == "Y") {
            if (!confirm('주식관련채권 상세내역이 존재합니다.\n특이채권유형 변경시 저장된 내용이 삭제됩니다.\n계속 진행하시겠습니까?')) {
                fm.nusual_bnd_tp_cd[1].setValue(1);
                return;
            }
        }
        $("#a_nusual_bnd_tp_cd").attr("disabled", "disabled");
        fm.stk_save_yn.setValue("N");

        //상태변경시 값초기화
        fm.stk_rel_corpbnd_rght_tp_cd.setValue('');
        fm.obj_isu_nm.setValue('');
        fm.obj_isu_cd.setValue('');
        fm.stk_rel_corpbnd_exer_prc.setValue('');
        fm.exer_rto.setValue('');
        fm.exer_strt_dd.setValue('');
        fm.exer_end_dd.setValue('');
        fm.cash_pay_yn.setValue('');
        fm.sb_pay_yn.setValue('');
        fm.paymethd_rto_contn.setValue('');
        fm.clm_inst_cd.setValue('');
        fm.clm_inst_nm.setValue('');
        fm.div_reck_dd_tp_cd.setValue('');
        fm.proft_partc_acc_yn.setValue('');

        //채권정합성추가
        fm.exer_prc_adj_mktprc_dn_yn.setValue('');
        fm.fst_exer_prc_adj_dd.setValue('');
        fm.stkcert_mmend_tp_cd.setValue('');
        fm.exer_prc_adj_cycle.setValue('');
        fm.exer_prc_adj_cnt.setValue('');
        fm.exer_prc_count.setValue('');
        $("#tbl_exer_prc tr").remove();

        //분리형BW여부 값초기화
        if (fm.detach_bw_yn.checked) {
            fm.stk_rel_corpbnd_rght_tp_cd.setValue('21');
        } else {
            fm.stk_rel_corpbnd_rght_tp_cd.setValue('');
        }
    } else if (fm.nusual_bnd_tp_cd[1].checked) {
        //분리형bw여부 체크확인
        if (fm.detach_bw_yn.checked) {
            alert("분리형 BW 체크 시 주권관련채권은 선택할 수 없습니다.");
            fm.nusual_bnd_tp_cd[0].setValue(1);
            return;
        }

        //권리구분값 초기화
        //fm.stk_rel_corpbnd_rght_tp_cd.value = ''

        $("#a_nusual_bnd_tp_cd").removeAttr("disabled");
        var url = "/listeach/eachListing.do?method=popupStkRltnBndCd" + "&stk_rel_corpbnd_rght_tp_cd=" + fm.stk_rel_corpbnd_rght_tp_cd.getValue() + "&obj_isu_cd=" + fm.obj_isu_cd.getValue() + "&stk_rel_corpbnd_exer_prc=" + fm.stk_rel_corpbnd_exer_prc.getValue() + "&exer_rto=" + fm.exer_rto.getValue() + "&exer_strt_dd=" + fm.exer_strt_dd.getValue() + "&exer_end_dd=" + fm.exer_end_dd.getValue() + "&cash_pay_yn=" + fm.cash_pay_yn.getValue() + "&sb_pay_yn=" + fm.sb_pay_yn.getValue() + "&paymethd_rto_contn=" + fm.paymethd_rto_contn.getValue() + "&clm_inst_cd=" + fm.clm_inst_cd.getValue() + "&div_reck_dd_tp_cd=" + fm.div_reck_dd_tp_cd.getValue() + "&proft_partc_acc_yn=" + fm.proft_partc_acc_yn.getValue();
        var style = "dialogWidth:720px;dialogHeight:870px;scroll:yes;resize__no";
        var rswin = window.showModalDialog(url, window, style);
    } else if (fm.nusual_bnd_tp_cd[2].checked) {
        //전자단기채권

        if (fm.stk_save_yn.getValue() == "Y") {
            if (!confirm('주식관련채권 상세내역이 존재합니다.\n특이채권유형 변경시 저장된 내용이 삭제됩니다.\n계속 진행하시겠습니까?')) {
                fm.nusual_bnd_tp_cd[1].setValue(1);
                return;
            }
        }
        $("#a_nusual_bnd_tp_cd").attr("disabled", "disabled");
        fm.stk_save_yn.setValue("N");

        //상태변경시 값초기화
        fm.stk_rel_corpbnd_rght_tp_cd.setValue('');
        fm.obj_isu_nm.setValue('');
        fm.obj_isu_cd.setValue('');
        fm.stk_rel_corpbnd_exer_prc.setValue('');
        fm.exer_rto.setValue('');
        fm.exer_strt_dd.setValue('');
        fm.exer_end_dd.setValue('');
        fm.cash_pay_yn.setValue('');
        fm.sb_pay_yn.setValue('');
        fm.paymethd_rto_contn.setValue('');
        fm.clm_inst_cd.setValue('');
        fm.clm_inst_nm.setValue('');
        fm.div_reck_dd_tp_cd.setValue('');
        fm.proft_partc_acc_yn.setValue('');

        //채권정합성추가
        fm.exer_prc_adj_mktprc_dn_yn.setValue('');
        fm.fst_exer_prc_adj_dd.setValue('');
        fm.stkcert_mmend_tp_cd.setValue('');
        fm.exer_prc_adj_cycle.setValue('');
        fm.exer_prc_adj_cnt.setValue('');
        fm.exer_prc_count.setValue('');
        $("#tbl_exer_prc tr").remove();
    }
    fnCrdtChange();
    return;
};


//변동금리관련
/**
 * @method
 * @name PopUp_int_pay_mth
 * @description desc
 * @param {string} fm desc
 * @param {string} selected_str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.PopUp_int_pay_mth = function(fm, selected_str) {
    var fm = document.SendForm;

    //필수입력사항 체크
    if (selected_str == "button") {
        if (fm.int_pay_methd_cd[0].checked || fm.int_pay_methd_cd[1].checked || fm.int_pay_methd_cd[2].checked || fm.int_pay_methd_cd[3].checked ||
            fm.int_pay_methd_cd[4].checked || fm.int_pay_methd_cd[5].checked) {
            alert('이자지급방법이 고정금리형인 경우 입력할 수 없습니다.');
            return;
        }
    }
    var temp = false;
    for (var i = 0; i <= 12; i++) {
        if (fm.int_pay_methd_cd[i].checked) {
            temp = true;
            break;
        }
    }
    if (!temp) {
        alert("이자지급방법을 선택해주십시오.");
        fm.int_pay_methd_cd[0].focus();
        return;
    }
    if (GetByte(fm.isu_amt.getValue()) == 0) {
        alert("발행금액을 입력해주십시오.");
        fm.isu_amt.focus();
        return;
    }
    if (GetByte(fm.list_amt.getValue()) == 0) {
        alert("상장금액을 입력해주십시오.");
        fm.list_amt.focus();
        return;
    }
    if (GetByte(fm.isu_dd.getValue()) == 0) {
        alert("발행일을 입력해주십시오.");
        fm.isu_dd.focus();
        return;
    }
    if (GetByte(fm.redmpt_dd.getValue()) == 0) {
        alert("상환일을 입력해주십시오.");
        fm.redmpt_dd.focus();
        return;
    }
    if (!fm.curr_tp_cd[0].checked && !fm.curr_tp_cd[1].checked && !fm.curr_tp_cd[2].checked && !fm.curr_tp_cd[3].checked && !fm.curr_tp_cd[4].checked) {
        alert("발행통화를 선택해주십시오.");
        fm.curr_tp_cd[0].focus();
        return;
    }
    if (GetByte(fm.coupn_rt.getValue()) == 0) {
        alert("표면이자율을 입력해주십시오.");
        fm.coupn_rt.focus();
        return;
    }

    //복리채,단리채,할인채,복5단2의 경우 이자지급주기를 받지않아도됨
    if (!fm.int_pay_methd_cd[1].checked && !fm.int_pay_methd_cd[2].checked && !fm.int_pay_methd_cd[3].checked && !fm.int_pay_methd_cd[4].checked) {
        if (GetByte(fm.int_pay_unit_mms.getValue()) == 0) {
            alert("이자지급주기를 입력해주십시오.");
            fm.int_pay_unit_mms.focus();
            return;
        }
    }

    //최초이자지급일 계산 - 1. null 이거나 0 이면 계산안함 / 2. 상환방법이 영구채이면 계산안함
    if (!fm.redmpt_methd_tp_cd[4].checked) {
        if (GetByte(fm.int_pay_unit_mms.getValue()) > 0 && fm.int_pay_unit_mms.getValue() != "0") {
            getFstIntPayDd(fm.isu_dd.getValue(), fm.redmpt_dd.getValue(), fm.int_pay_unit_mms.getValue());
        }
    }

    //if (fm.int_pay_methd_cd[0].checked || fm.int_pay_methd_cd[6].checked || fm.int_pay_methd_cd[7].checked) {
    if (GetByte(fm.fst_int_pay_dd.getValue()) == 0) {
        alert("최초 이자지급일을 입력해주십시오.");
        fm.fst_int_pay_dd.focus();
        return;
    }
    var fstIntPayDdCheck = fm.fst_int_pay_dd_check.getValue();
    var fstIntPayDd = fm.fst_int_pay_dd.getValue().replace(/-/gi, "");
    if (fstIntPayDdCheck != fstIntPayDd) {
        if (!confirm("최초 이자지급일이 '발행일 + 이자지급주기'에 맞지 않습니다.\n그래도 처리하시겠습니까?")) {
            fm.fst_int_pay_dd.focus();
            return false;
        }
    }
    //}



    //이자지급방법 변동금리채 일때 
    if (fm.int_pay_methd_cd[6].checked || fm.int_pay_methd_cd[7].checked || fm.int_pay_methd_cd[8].checked || fm.int_pay_methd_cd[9].checked) {
        //버튼 onclick이벤트 설정
        $("#a_int_pay_methd_cd").removeAttr("disabled");

        //상태변경시 값초기화 - 원리금부분
        fm.princint_change.setValue('Y');
        fm.princint_count.setValue('0');
        $("#tbl_princint tr").remove();


        //변동금리팝업
        if (fm.int_rt_chg_cnt.getValue() == "") {
            fm.int_rt_chg_cnt.setValue("0");
        }
        if (fm.redmpt_dd.getValue() == null || fm.redmpt_dd.getValue().length == 0) {
            alert("상환일을 먼저 입력해주십시오.\n\n영구채인 경우 상환방법을 영구채로 지정하면\n상환일이 '9999-12-31'로 자동 지정됨");
            fm.redmpt_dd.focus();
            fm.int_pay_methd_cd[0].setValue(1);
            $("#a_int_pay_methd_cd").attr("disabled", "disabled");
            return;
        }
        var url = "";
        if (fm.int_pay_methd_cd[6].checked) {
            url = "/listeach/eachListing.do?method=popupIntPayMth&gubun=3";
            //저장된상태값 저장
            fm.status_int_pay_methd_cd.setValue("7");
        } else if (fm.int_pay_methd_cd[7].checked) {
            url = "/listeach/eachListing.do?method=popupIntPayMth&gubun=5";
            //저장된상태값 저장
            fm.status_int_pay_methd_cd.setValue("11");
        } else if (fm.int_pay_methd_cd[8].checked) {
            url = "/listeach/eachListing.do?method=popupIntPayMth&gubun=6";
            //저장된상태값 저장
            fm.status_int_pay_methd_cd.setValue("12");
        } else if (fm.int_pay_methd_cd[9].checked) {
            url = "/listeach/eachListing.do?method=popupIntPayMth&gubun=7";
            //저장된상태값 저장
            fm.status_int_pay_methd_cd.setValue("13");
        }
        //url = "/listeach/eachListing.do?method=popupIntPayMth";
        var style = "dialogWidth:820px;dialogHeight:750px;scroll:yes;resize__no";
        var rswin = window.showModalDialog(url, window, style);
    } else {
        if (fm.int_rt_save_yn.getValue() == "Y") {
            if (!confirm('변동금리 상세내역이 존재합니다.\n고정금리형 선택시 저장된 내용이 삭제됩니다.\n계속 진행하시겠습니까?')) {
                if (fm.status_int_pay_methd_cd.getValue() == "7") {
                    fm.int_pay_methd_cd[6].setValue(1);
                } else if (fm.status_int_pay_methd_cd.getValue() == "11") {
                    fm.int_pay_methd_cd[7].setValue(1);
                } else if (fm.status_int_pay_methd_cd.getValue() == "12") {
                    fm.int_pay_methd_cd[8].setValue(1);
                } else if (fm.status_int_pay_methd_cd.getValue() == "13") {
                    fm.int_pay_methd_cd[9].setValue(1);
                }
                return;
            }
        }

        //버튼 onclick이벤트 설정
        $("#a_int_pay_methd_cd").attr("disabled", "disabled");
        fm.int_rt_save_yn.setValue("N");

        //상태변경시 값초기화 - 변동금리부분
        fm.coupn_rt_decsn_bas_int_cd.setValue('');
        fm.int_rt_decsn_misc_bas_int_nm.setValue('');
        fm.spd_sgn.setValue('');
        fm.spd.setValue('');
        fm.int_rt_decsn_tm_cd.setValue('');
        fm.uplmt_coupn_rt.setValue('');
        fm.lwlmt_coupn_rt.setValue('');
        fm.int_rt_decsn_bas_dd.setValue('');
        fm.frn_bas_int_tp_cd1.setValue('');
        fm.frn_bas_int_tp_cd2.setValue('');
        fm.frn_bas_int_tp_cd3.setValue('');
        fm.frn_bas_int_tp_cd4.setValue('');
        fm.frn_bas_int_misc.setValue('');

        //채권정합성추가
        fm.int_pay_cnt.setValue('');
        fm.int_decsn_regul_yn.setValue('');
        fm.int_decsn_nregul_rsn_contn.setValue('');
        fm.int_decsn_bas_tp_cd.setValue('');
        fm.int_decsn_bas_dys.setValue('');
        fm.int_rt_chg_cnt.setValue('');
        $("#tbl_int_chg_dt tr").remove();

        //상태변경시 값초기화 - 표면이자율부분
        fm.coupn_rt_decsn_bas_int_cd.setValue('');
        fm.coupn_rt_remain_pd_cd.setValue('');
        fm.coupn_rt_decsn_spd_sgn.setValue('');
        fm.coupn_rt_decsn_spd.setValue('');
        fm.coupn_rt_decsn_bas_dd.setValue('');
        fm.coupn_rt_decsn_tm.setValue('');
        fm.coupn_rt_misc_bas_int_contn.setValue('');
    }
    return;
};


// 표면이자율 결정
