//옵션관련
/**
 * @method
 * @name PopUp_opt_bnd_cd
 * @description desc
 * @param {string} fm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.PopUp_opt_bnd_cd = function(fm) {
    var fm = document.SendForm;
    var url = "";
    if (fm.imbdopt_corpbnd_cd[3].checked) {
        if (fm.call_save_yn.getValue() == "Y" || fm.put_save_yn.getValue() == "Y") {
            if (!confirm('옵션 상세내역이 존재합니다.\n옵션 변경시 저장된 내용이 삭제됩니다.\n계속 진행하시겠습니까?')) {
                if (fm.status_imbdopt_corpbnd_cd.getValue() == "1") {
                    fm.imbdopt_corpbnd_cd[0].setValue(1);
                } else if (fm.status_imbdopt_corpbnd_cd.getValue() == "2") {
                    fm.imbdopt_corpbnd_cd[1].setValue(1);
                } else if (fm.status_imbdopt_corpbnd_cd.getValue() == "3") {
                    fm.imbdopt_corpbnd_cd[2].setValue(1);
                }
                return;
            }
        }

        //저장된상태값 삭제
        fm.status_imbdopt_corpbnd_cd.setValue("");

        //버튼 onclick이벤트 설정
        $("#a_imbdopt_corpbnd_cd").attr("disabled", "disabled");
        fm.call_save_yn.setValue("N");
        fm.put_save_yn.setValue("N");
        fm.call_magnt_tp_cd.setValue('');
        fm.call_exer_rsn.setValue('');
        fm.fst_call_exer_dd.setValue('');
