/**
 * @method
 * @name PopUp_liq_cd
 * @description desc
 * @param {string} fm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.PopUp_liq_cd = function(fm) {
    var fm = document.SendForm;
    if (fm.hbrdbnd_yn[0].checked) {
        alert("신종자본증권인 경우 유동화는 선택하실 수 없습니다.");
        fm.asst_secutiz_tp_cd[7].setValue(1);
        return;
    }
    if (fm.cond_cap_secu_tp_cd[0].checked || fm.cond_cap_secu_tp_cd[1].checked) {
        alert("조건부자본증권인 경우 유동화는 선택하실 수 없습니다.");
        fm.asst_secutiz_tp_cd[7].setValue(1);
        return;
    }
    if (fm.asst_secutiz_tp_cd[7].checked) {
        if (fm.asst_save_yn.getValue() == "Y") {
            if (!confirm('유동화 상세내역이 존재합니다.\n유동화 유형 변경시 저장된 내용이 삭제됩니다.\n계속 진행하시겠습니까?')) {
                if (fm.status_asst_secutiz_tp_cd.getValue() == "11") {
                    fm.asst_secutiz_tp_cd[0].setValue(1);
                } else if (fm.status_asst_secutiz_tp_cd.getValue() == "12") {
                    fm.asst_secutiz_tp_cd[1].setValue(1);
                } else if (fm.status_asst_secutiz_tp_cd.getValue() == "13") {
                    fm.asst_secutiz_tp_cd[2].setValue(1);
                } else if (fm.status_asst_secutiz_tp_cd.getValue() == "21") {
                    fm.asst_secutiz_tp_cd[3].setValue(1);
                } else if (fm.status_asst_secutiz_tp_cd.getValue() == "22") {
                    fm.asst_secutiz_tp_cd[4].setValue(1);
                } else if (fm.status_asst_secutiz_tp_cd.getValue() == "31") {
                    fm.asst_secutiz_tp_cd[5].setValue(1);
                } else if (fm.status_asst_secutiz_tp_cd.getValue() == "32") {
                    fm.asst_secutiz_tp_cd[6].setValue(1);
                }
                return;
            }
        }

        //버튼 onclick이벤트 설정
        $("#a_asst_secutiz_tp_cd").attr("disabled", "disabled");
        fm.asst_save_yn.setValue("N");

        //유동화 해당없음 선택시 유동화 저장내용삭제
        fm.secutiz_adm_inst_cd.setValue('');
        fm.secutiz_adm_inst_nm.setValue('');
        fm.secutiz_chrg_nm.setValue('');
        fm.secutiz_chrg_tel_no.setValue('');
        fm.encryp_secutiz_chrg_email.setValue('');
        fm.secutiz_schdl_isu_totamt.setValue('');
        fm.secutiz_asst_tot_valu_amt.setValue('');
        fm.credit_refoce_methd_contn.setValue('');
        fm.secutiz_misc_memo_contn.setValue('');
        fm.asst_count.setValue('0');
        $("#tbl_asst tr").remove();
    } else {
        //유동화 선택시 신용평가내용이 미작성상태이면 SF활성화 및 자동체크
        /*if( !fm.credit_valu_chk1.checked && !fm.credit_valu_chk2.checked && !fm.credit_valu_chk3.checked && !fm.credit_valu_chk4.checked ){
	    		fm.credit_valu_inst_cd1.value = '9201';
	    		fm.credit_valu_chk1.checked = true;
	    		fm.byinst_credit_valu_grd1.disabled = false;
				fm.sf_valu_yn1.disabled = false;
				fm.sf_valu_yn1.checked = true;
	    	}*/

        //버튼 onclick이벤트 설정
        $("#a_asst_secutiz_tp_cd").removeAttr("disabled");

        //저장된상태값 저장
        fm.status_asst_secutiz_tp_cd.setValue($("input[name='asst_secutiz_tp_cd']:checked").val());
        var url = "/listeach/eachListing.do?method=popupLiqCd";
        var style = "dialogWidth:740px;dialogHeight:800px;scroll:yes;resize__no";
        var rswin = window.showModalDialog(url, window, style);
        return;
    }
};



