// 보증-무보증 관련
/**
 * @method
 * @name Msg_grt_cd
 * @description desc
 * @param {string} fm desc
 * @param {string} checkval desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Msg_grt_cd = function(fm, checkval) {
    //보증/담보 선택값에 따라
    if (fm.bnd_guar_tp_cd[4].checked) {
        //정부보증
        $("input[name='grt_rt']").attr("readonly", false);
        $("input[name='grt_rt']").attr("style", "background:");
        fm.grt_rt.setValue('');
    } else if (fm.bnd_guar_tp_cd[1].checked) {
        //보증
        $("input[name='grt_rt']").attr("readonly", true);
        $("input[name='grt_rt']").attr("style", "background:#e2e2e2");
        fm.grt_rt.setValue('100');
    } else if (fm.bnd_guar_tp_cd[2].checked) {
        //부분보증
        $("input[name='grt_rt']").attr("readonly", false);
        $("input[name='grt_rt']").attr("style", "background:");
        fm.grt_rt.setValue('');
    } else if (fm.bnd_guar_tp_cd[3].checked || fm.bnd_guar_tp_cd[5].checked) {
        //담보부, 커버드본드
        $("input[name='grt_rt']").attr("readonly", true);
        $("input[name='grt_rt']").attr("style", "background:#e2e2e2");
        fm.grt_rt.setValue('');
    } else if (fm.bnd_guar_tp_cd[0].checked) {
        //무보증
        $("input[name='grt_rt']").attr("readonly", true);
        $("input[name='grt_rt']").attr("style", "background:#e2e2e2");
        fm.grt_rt.setValue('');
    } else {
        //이외
        $("input[name='grt_rt']").attr("readonly", true);
        $("input[name='grt_rt']").attr("style", "background:#e2e2e2");
        fm.grt_rt.setValue('');
    }
    var chkval = checkval;

    //if (chkval != 4 && fm.grt_rt.value == '') {
    //   alert("무보증 이외 조건 선택시에는 \n\r보증률을 입력하셔야됩니다.");
    //    fm.grt_rt.focus();
    //} else if (chkval == 4) {
    //	fm.grt_rt.value = '';
    //}

    if (chkval == 5) {
        fm.grt_inst_cd.setValue('1001');
        fm.grt_inst_nm.setValue('정부');
    }
};



