/**
 * @method
 * @name NewLstCheckValues
 * @description desc
 * @param {string} fm desc
 * @param {string} bnd_mktact_tp_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.NewLstCheckValues = function(fm, bnd_mktact_tp_cd) {
    var fm = document.SendForm;

    /*
    alert("cb_bank_int_pay_cd=" +fm.cb_bank_int_pay_cd.value );
    alert("cb_bank_int_pay_cd_1=" +fm.cb_bank_int_pay_cd_1.value );
    alert("cb_bank_int_pay_cd_rt=" +fm.cb_bank_int_pay_cd_rt.value );
    alert("cb_bank_pri_pay_cd=" +fm.cb_bank_pri_pay_cd.value );
    alert("cb_bank_pri_pay_cd_1=" +fm.cb_bank_pri_pay_cd_1.value );
    alert("cb_bank_pri_pay_cd_rt=" +fm.cb_bank_pri_pay_cd_rt.value );
    return;
    */

    //	    if (!krxYn(fm.krx_yn.value)) {
    //       return;
    //  }

    //###################### 종목명 ###########################
    if (GetByte(fm.appl_isu_nm.getValue()) == 0) {
        alert("한글종목명을 입력해주십시오.");
        fm.appl_isu_nm.focus();
        return;
    }
    if (GetByte(fm.appl_isu_eng_nm.getValue()) == 0) {
        alert("영문종목명을 선택해주십시오.");
        fm.appl_isu_eng_nm.focus();
        return;
    }

    //###################### 채권분류 #########################
    if (GetByte(fm.isu_amt.getValue()) == 0) {
        alert("발행금액을 입력해주십시오.");
        fm.isu_amt.focus();
        return;
    }
    if (GetByte(fm.list_amt.getValue()) == 0) {
        alert("상장금액을 입력해주십시오.");
        fm.list_amt.focus();
        return;
    }

    //발행금액 >= 상장금액 체크
    if (parseInt(Del_MoneyComma_Value(fm.isu_amt.getValue())) < parseInt(Del_MoneyComma_Value(fm.list_amt.getValue()))) {
        alert("상장금액은 발행금액 보다 작거나 같아야 합니다.");
        fm.list_amt.focus();
        return;
    }
    if (GetByte(fm.isu_dd.getValue()) == 0) {
        alert("발행일을 입력해주십시오.");
        fm.isu_dd.focus();
        return;
    }
    if (GetByte(fm.procs_req_dd.getValue()) == 0) {
        if (fm.bnd_mktact_tp_cd.getValue() == '113') {
            alert("WIT개시희망일을 입력해주십시오.");
        } else {
            alert("상장희망일을 입력해주십시오.");
        }
        fm.procs_req_dd.focus();
        return;
    }
    if (scwin.fnToday() >= fm.procs_req_dd.getValue().replace("-", "").replace("-", "")) {
        if (fm.bnd_mktact_tp_cd.getValue() == '113') {
            alert("WIT개시희망일은 신청일 익일 이후만 입력가능합니다.");
        } else {
            alert("상장희망일은 신청일 익일 이후만 입력가능합니다.");
        }
        fm.procs_req_dd.focus();
        return;
    }

    //상장희망일 - 매매일체크
    Chk_Mkt_Holdy(fm.procs_req_dd);
    if (fm.procs_req_dd_check.getValue() == 'Y') {
        if (fm.bnd_mktact_tp_cd.getValue() == '113') {
            alert("WIT개시희망일은  매매일만 입력가능합니다.");
        } else {
            alert("상장희망일은  매매일만 입력가능합니다.");
        }
        fm.procs_req_dd.focus();
        return;
    }
    if (GetByte(fm.redmpt_dd.getValue()) == 0) {
        alert("상환일을 선택해주십시오.");
        fm.redmpt_dd.focus();
        return;
    }
    if (fm.infllnk_yn.getValue() == 'N' && GetByte(fm.isu_dd_ref_idx.getValue()) > 0) {
