    //주식관련사채 선택일때 보장수익률이나 추가수익률 값 체크
    /*if( fm.nusual_bnd_tp_cd[1].checked ){
	    	if(GetByte(fm.grt_yd.value) <= 0 && GetByte(fm.add_yd.value) <= 0){
	    		if(confirm('보장수익률과 추가수익률이 입력되지 않았습니다.\n계속 진행하시겠습니까?')){
	    		}else{
		    		fm.grt_yd.focus();
		    		return;
	    		}
	    	}
	    }*/ //중복체크 제거

    if (fm.nusual_bnd_tp_cd[1].checked) {
        if (GetByte(fm.grt_yd.getValue()) <= 0) {
            if (confirm('보장수익률이 입력되지 않았습니다.\n계속 진행하시겠습니까?')) {

