            }
        }
    }
    //보장수익률 값 있을경우 보장수익률 날짜 누락체크
    if (GetByte(fm.grt_yd.getValue()) > 0 && GetByte(fm.grt_yd_strt_dd.getValue()) <= 0) {
        alert("보장수익률 입력시 보장수익률적용일을 입력해야합니다.");
