    }
    if (fm.nusual_bnd_tp_cd[1].checked) {
        if (GetByte(fm.add_yd.getValue()) <= 0) {
            if (confirm('추가수익률이 입력되지 않았습니다.\n계속 진행하시겠습니까?')) {

