    }

    //국채 이외인 경우만 체크
    if (fm.bnd_mktact_tp_cd.getValue() != '113' && fm.bnd_mktact_tp_cd.getValue() != '111' && !fm.asst_secutiz_tp_cd[7].checked &&
        (fm.credit_valu_chk1.checked == false || fm.byinst_credit_valu_grd1.getValue() == '') &&
        (fm.credit_valu_chk2.checked == false || fm.byinst_credit_valu_grd2.getValue() == '') &&
        (fm.credit_valu_chk3.checked == false || fm.byinst_credit_valu_grd3.getValue() == '') &&
        (fm.credit_valu_chk4.checked == false || fm.byinst_credit_valu_grd4.getValue() == '')) {
        if (!confirm('유동화채권임에도 SF를 선택하지 않았습니다. 계속진행하시겠습니까?')) {
            return;
        }
    }

    //###################### 이메일수신 동의여부(2011-02-16 최진호) #########################
    //if(fm.email_rcv_yn.checked == true) {
    //	fm.email_rcv_yn.value = "Y";
    //}
    //else {
    //	fm.email_rcv_yn.value = "N";
    //}

    //최초이자지급일 계산 - 1. null 이거나 0 이면 계산안함 / 2. 상환방법이 영구채이면 계산안함
    //if( !fm.redmpt_methd_tp_cd[4].checked ){
    if (GetByte(fm.int_pay_unit_mms.getValue()) > 0 && fm.int_pay_unit_mms.getValue() != "0") {
        getFstIntPayDd(fm.isu_dd.getValue(), fm.redmpt_dd.getValue(), fm.int_pay_unit_mms.getValue());
    }
    //}

    //공통 필터링
    if (scwin.CommonCheckValues(fm, bnd_mktact_tp_cd)) {
        //팝업화면 미작성 체크
        //주식관련사채상세내역
        if (fm.nusual_bnd_tp_cd[1].checked && fm.stk_save_yn.getValue() == "N") {
            alert("주식관련사채 상세내역입력이 완료되지 않았습니다.");
            scwin.PopUp_stk_rltn_bnd_cd(fm);
            return;
        }
        //변동금리상세내역
        if (!fm.int_pay_methd_cd[0].checked &&
            !fm.int_pay_methd_cd[1].checked &&
            !fm.int_pay_methd_cd[2].checked &&
            !fm.int_pay_methd_cd[3].checked &&
            !fm.int_pay_methd_cd[4].checked &&
            !fm.int_pay_methd_cd[5].checked && fm.int_rt_save_yn.getValue() == "N") {
            alert("변동금리 상세내역입력이 완료되지 않았습니다.");
            scwin.PopUp_int_pay_mth(fm);
            return;
        }
        //표면이자율상세내역
        /*if( fm.coupn_rt_save_yn.value == "N" ){
        	alert("표면이자율 상세내역입력이 완료되지 않았습니다.");
        	PopUp_cpn_int_rt(fm);
        	return;
        }
        //발행가액상세내역
        if( fm.isu_prc_save_yn.value == "N" ){
        	alert("발행가액 상세내역입력이 완료되지 않았습니다.");
        	PopUp_iss_pr(fm);
        	return;
        }*/
        //Call상세내역
        if ((fm.imbdopt_corpbnd_cd[0].checked || fm.imbdopt_corpbnd_cd[2].checked) && fm.call_save_yn.getValue() == "N") {
            alert("CALL옵션 상세내역입력이 완료되지 않았습니다.");
            scwin.PopUp_opt_bnd_cd(fm);
            return;
        }
        //Put상세내역
        if ((fm.imbdopt_corpbnd_cd[1].checked || fm.imbdopt_corpbnd_cd[2].checked) && fm.put_save_yn.getValue() == "N") {
            alert("PUT옵션 상세내역입력이 완료되지 않았습니다.");
            scwin.PopUp_opt_bnd_cd(fm);
            return;
        }
        //분할상환(원금균등/원리금균등)상세내역
        if ((fm.redmpt_methd_tp_cd[1].checked || fm.redmpt_methd_tp_cd[2].checked) && fm.eq_save_yn.getValue() == "N") {
            alert("분할상환 원금/원리금균등 상세내역입력이 완료되지 않았습니다.");
            scwin.PopUp_rdmp_mth(fm);
            return;
        }
        //분할상환(불균등)상세내역
        if (fm.redmpt_methd_tp_cd[3].checked && fm.non_eq_save_yn.getValue() == "N") {
            alert("분할상환 불균등 상세내역입력이 완료되지 않았습니다.");
            scwin.PopUp_rdmp_mth(fm);
            return;
        }
        //유동화상세내역
        /*if( !fm.asst_secutiz_tp_cd[0].checked && !fm.asst_secutiz_tp_cd[1].checked && !fm.asst_secutiz_tp_cd[2].checked && !fm.asst_secutiz_tp_cd[3].checked && !fm.asst_secutiz_tp_cd[4].checked && !fm.asst_secutiz_tp_cd[5].checked && !fm.asst_secutiz_tp_cd[6].checked ){
        	alert("유동화가 선택되지 않았습니다.");
        	PopUp_liq_cd(fm);
        	return;
        }*/
        //국채 이외인 경우만 체크
        if (fm.bnd_mktact_tp_cd.getValue() != '113' && fm.bnd_mktact_tp_cd.getValue() != '111') {
            if (!fm.asst_secutiz_tp_cd[7].checked && fm.asst_save_yn.getValue() == "N") {
                alert("유동화 상세내역입력이 완료되지 않았습니다.");
                scwin.PopUp_liq_cd(fm);
                return;
            }
        }
        //원리금상세내역
        //이자지급방법이 고정금리형일 경우 원리금 입력 필수 - 표면이자율 미확정시는 제외
        //고정금리형 중 할인채와 기타의 경우는 입력안하는 케이스도 있기때문에 제외
        if (!fm.redmpt_methd_tp_cd[4].checked) {
            //영구채 제외
            if (fm.coupn_rt_final_yn[0].checked && (fm.int_pay_methd_cd[0].checked || fm.int_pay_methd_cd[1].checked || fm.int_pay_methd_cd[2].checked || fm.int_pay_methd_cd[4].checked)) {
                if (fm.princint_save_yn.getValue() == "N") {
