                    }
                }
            }

            //상장금액 = 발행용도 총계
            if (GetByte(fm.eqmt_fnd.getValue()) > 0 || GetByte(fm.oper_fnd.getValue()) > 0 || GetByte(fm.refund_fnd.getValue()) > 0 || GetByte(fm.misc_fnd.getValue()) > 0) {
                var eqmt = fm.eqmt_fnd.getValue();
                var oper = fm.oper_fnd.getValue();
                var refund = fm.refund_fnd.getValue();
                var misc = fm.misc_fnd.getValue();
                if (eqmt == "") {
                    eqmt = "0";
                }
                if (oper == "") {
                    oper = "0";
                }
                if (refund == "") {
                    refund = "0";
                }
                if (misc == "") {
                    misc = "0";
                }
                var cmt1 = parseInt(Del_MoneyComma_Value(eqmt)) + parseInt(Del_MoneyComma_Value(oper)) + parseInt(Del_MoneyComma_Value(refund)) + parseInt(Del_MoneyComma_Value(misc));
                if (parseInt(Del_MoneyComma_Value(fm.list_amt.getValue())) != cmt1) {
                    alert("상장금액과 발행용도 자금 총계가 일치하지 않습니다.");
                    fm.eqmt_fnd.focus();
                    return;
                }
            }
            //상장금액 = 인수금액 총계
            if (GetByte(fm.udwrt_amt1.getValue()) > 0 || GetByte(fm.udwrt_amt2.getValue()) > 0 || GetByte(fm.udwrt_amt3.getValue()) > 0 || GetByte(fm.udwrt_amt4.getValue()) > 0 || GetByte(fm.udwrt_amt5.getValue()) > 0) {
                var udwrt1 = fm.udwrt_amt1.getValue();
                var udwrt2 = fm.udwrt_amt2.getValue();
                var udwrt3 = fm.udwrt_amt3.getValue();
                var udwrt4 = fm.udwrt_amt4.getValue();
                var udwrt5 = fm.udwrt_amt5.getValue();
                if (udwrt1 == "") {
                    udwrt1 = "0";
                }
                if (udwrt2 == "") {
                    udwrt2 = "0";
                }
                if (udwrt3 == "") {
                    udwrt3 = "0";
                }
                if (udwrt4 == "") {
                    udwrt4 = "0";
                }
                if (udwrt5 == "") {
                    udwrt5 = "0";
                }
                var cmt2 = parseInt(Del_MoneyComma_Value(udwrt1)) + parseInt(Del_MoneyComma_Value(udwrt2)) + parseInt(Del_MoneyComma_Value(udwrt3)) + parseInt(Del_MoneyComma_Value(udwrt4)) + parseInt(Del_MoneyComma_Value(udwrt5));
                if (parseInt(Del_MoneyComma_Value(fm.list_amt.getValue())) != cmt2) {
                    alert("상장금액과 인수금액 총계가 일치하지 않습니다.");
                    fm.udwrt_amt1.focus();
                    return;
                }
            }

            //국채신규상장이고 국고채권(GB035), 한국은행(AB101), 예금보험공사(AB526) 발행기관의 경우 낙찰금리 입력체크 경고창
            if (fm.bnd_mktact_tp_cd.getValue() == '111' && (fm.isur_cd.getValue() == 'GB035' || fm.isur_cd.getValue() == 'AB101' || fm.isur_cd.getValue() == 'AB526')) {
                if (GetByte(fm.scbd_int.getValue()) == 0) {
                    if (!confirm("낙찰금리가 입력되지 않았습니다.\n계속 진행하시겠습니까?")) {
                        fm.scbd_int.focus();
                        return false;
                    }
                }
            }

            //발행금액과 상장금액이 1억원 이하 일때 주의팝업
            if (parseInt(Del_MoneyComma_Value(fm.isu_amt.getValue())) < 100000000 && parseInt(Del_MoneyComma_Value(fm.list_amt.getValue())) < 100000000) {
                alert("발행금액과 상장금액이 1억원 이하입니다.");
            } else {
                if (parseInt(Del_MoneyComma_Value(fm.isu_amt.getValue())) < 100000000) {
                    alert("발행금액이 1억원 이하입니다.");
                }
                if (parseInt(Del_MoneyComma_Value(fm.list_amt.getValue())) < 100000000) {
                    alert("상장금액이 1억원 이하입니다.");
                }
            }
            if (!confirm("신청하시겠습니까?")) {
                return false;
            }

            //회사채의 경우 내용 보여주기
            if (bnd_mktact_tp_cd == '141') {
                alert("사채납입 증명서는 납입일 오후까지 채권상장시스템\n파일업로드 메뉴에서 업로드 시키거나\n팩스(051-630-2751)로 반드시 보내주시기 바랍니다.");
            }
            fm.method.setValue("requestEachListing");
            fm.action = "/listeach/eachListing.do";
            fm.target = "_self";
            fm.submit();
        }
    }
};






/********************************* 오늘날짜 가져오기 *********************************/
/**
 * @method
 * @name fnToday
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fnToday = function() {
    var now = new Date();
    var year = now.getFullYear();
    var mon = (now.getMonth() + 1) > 9 ? '' + (now.getMonth() + 1) : '0' + (now.getMonth() + 1);
    var day = now.getDate() > 9 ? '' + now.getDate() : '0' + now.getDate();
    return (year + mon + day);
};




