            //국고채권(GB035), 한국은행(AB101), 예금보험공사(AB526) 발행기관의 경우 낙찰금리 입력체크 경고창
            if (fm.isur_cd.getValue() == 'GB035' || fm.isur_cd.getValue() == 'AB101' || fm.isur_cd.getValue() == 'AB526') {
                if (GetByte(fm.scbd_int.getValue()) == 0) {
                    if (!confirm("낙찰금리가 입력되지 않았습니다.\n계속 진행하시겠습니까?")) {
                        fm.scbd_int.focus();
                        return false;
                    }
                }
            }

            //마이너스입력체크
            if (fn_minusCheck(fm.coupn_rt, "표면이자율") == "N") {
                return false;
            }
            if (fn_minusCheck(fm.scbd_int, "낙찰금리") == "N") {
                return false;
            }
            if (fn_minusCheck(fm.bk_holdy_dd_princ_acrint_rt, "원금 경과금리") == "N") {
                return false;
            }
            if (fn_minusCheck(fm.bk_holdy_dd_int_cmp_acrint_rt, "이자 경과금리") == "N") {
                return false;
            }


            // 첨부파일 크기 체크(전체 파일사이즈 <= 100)  2024.05.14 by 김효준
            var totFileSize = sumAttachedFilesSize(); // MB
            if (totFileSize > 100) {
                alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
                return;
            }
            if (!confirm("신청하시겠습니까?")) {
                return false;
            }
            fm.method.setValue("requestBlocListing");
            fm.action = "/listbloc/blocListing.do";
            fm.target = "_self";
            fm.submit();
        }
    }
};





/************************* 신규상장 공통 Value Check ************************/
/**
 * @method
 * @name CommonCheckValues
 * @description desc
 * @param {string} fm desc
 * @param {string} bnd_mktact_tp_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.CommonCheckValues = function(fm, bnd_mktact_tp_cd) {
    var fm = document.SendForm;
    if (!fm.coupn_rt_final_yn[0].checked && !fm.coupn_rt_final_yn[1].checked) {
        alert("표면이자율 확정여부를 선택해주십시오.");
        fm.coupn_rt_final_yn[0].focus();
        return;
    }


    //WIT종목지정의경우 '표면이자율 미확정'으로 선택해야함
    if (fm.bnd_mktact_tp_cd.getValue() == '113') {
        if (fm.coupn_rt_final_yn[0].checked) {
            alert("WIT종목지정의 경우 표면이자율 확정여부를\n\r'미확정'으로 선택해야합니다.");
            fm.coupn_rt_final_yn[0].focus();
            return;
        }
        if (GetByte(fm.coupn_rt.getValue()) != 0) {
            alert("WIT종목지정의 경우 표면이자율을 입력할 수 없습니다.");
            fm.coupn_rt.focus();
            return;
        }
    } else {
        if (fm.coupn_rt_final_yn[0].checked) {
            if (GetByte(fm.coupn_rt.getValue()) == 0) {
                alert("표면이자율확정시에는 표면이자율을 입력해주십시오.");
                fm.coupn_rt.focus();
                return;
            }
        }
        if (GetByte(fm.coupn_rt.getValue()) != 0) {
            if (fm.coupn_rt_final_yn[1].checked) {
                alert("표면이자율이 입력되었습니다.\n표면이자율 확정여부를 확인해주십시오.");
                fm.coupn_rt_final_yn[0].focus();
                return;
            }
        }
    }
    if (!fm.curr_tp_cd[0].checked && !fm.curr_tp_cd[1].checked && !fm.curr_tp_cd[2].checked && !fm.curr_tp_cd[3].checked && !fm.curr_tp_cd[4].checked) {
        alert("발행통화를 선택해주십시오.");
        fm.curr_tp_cd[0].focus();
        return;
    }

    // 보증-무보증 관련
    if (fm.bnd_guar_tp_cd[2].checked && fm.grt_rt.getValue() == "100") {
        alert(" 부분보증의 보증률은 '1 ~ 99' 범위에서 작성해야 합니다.");
        fm.grt_rt.focus();
        return false;
    }
    if ((fm.bnd_guar_tp_cd[1].checked || fm.bnd_guar_tp_cd[2].checked || fm.bnd_guar_tp_cd[4].checked) && (GetByte(fm.grt_inst_nm.getValue()) == 0)) {
        alert("보증, 부분보증, 정부보증선택시에는 \n\r보증기관을 선택해야합니다.");
        fm.grt_inst_nm.focus();
        return false;
    }
    if (fm.bnd_guar_tp_cd[4].checked && (fm.grt_inst_cd.getValue() != '1001' || fm.grt_inst_nm.getValue() != '정부')) {
        alert("정부보증선택시에는 \n\r보증기관을 '정부'로 선택해야합니다.");
        fm.grt_inst_nm.focus();
        return false;
    }
    if (bnd_mktact_tp_cd.substr(2, 1) != '2') {
        //개별	
        if (!fm.int_pay_methd_cd[0].checked &&
            !fm.int_pay_methd_cd[1].checked &&
            !fm.int_pay_methd_cd[2].checked &&
            !fm.int_pay_methd_cd[3].checked &&
            !fm.int_pay_methd_cd[4].checked &&
            !fm.int_pay_methd_cd[5].checked &&
            !fm.int_pay_methd_cd[6].checked &&
            !fm.int_pay_methd_cd[7].checked &&
            !fm.int_pay_methd_cd[8].checked &&
            !fm.int_pay_methd_cd[9].checked) {
            alert("이자지급방법을 선택해 주십시오");
            fm.int_pay_methd_cd[0].focus();
            return;
        }
    } else {
        //일괄
        if (!fm.int_pay_methd_cd[0].checked &&
            !fm.int_pay_methd_cd[1].checked &&
            !fm.int_pay_methd_cd[2].checked &&
            !fm.int_pay_methd_cd[3].checked &&
            !fm.int_pay_methd_cd[4].checked &&
            !fm.int_pay_methd_cd[5].checked &&
            !fm.int_pay_methd_cd[6].checked &&
            !fm.int_pay_methd_cd[7].checked &&
            !fm.int_pay_methd_cd[8].checked &&
            !fm.int_pay_methd_cd[9].checked) {
            alert("이자지급방법을 선택해 주십시오");
            fm.int_pay_methd_cd[0].focus();
            return;
        }
    }
    //2006.10.30 add 
    //추가 hj 2008.05.28 

    // jackal 09.11.09 디폴트 항목 셋팅으로 없어짐
    //if (fm.cb_bank_int_pay_cd.options[0].selected) {
    //    alert("은행휴무일 이자 또는 원리금지급방법을 입력하십시오.");
    //    fm.cb_bank_int_pay_cd.focus();
    //    return false;
    //}

    //임시주석 yakorgy
    /*if (bnd_mktact_tp_cd == '121' || bnd_mktact_tp_cd == '122' ) { //지방채
        if (fm.cb_local_cd.options[0].selected) {
            alert("지방채구분을 선택하십시오.");
            fm.cb_local_cd.focus();
            return false;
        }
    } else {
        if (!fm.cb_local_cd.options[0].selected) {
            alert("지방채인 경우만 선택하십시오.");
            fm.cb_local_cd.focus();
            return false;
        }
    }*/

    //###################### 발행방법 값 setting #########################
    if (bnd_mktact_tp_cd != '141') {
        //회사채아닐경우 사모채 보이게 설정
        if (!fm.ck_bnd_isu_methd_cd[0].checked && !fm.ck_bnd_isu_methd_cd[1].checked && !fm.ck_bnd_isu_methd_cd[2].checked) {
            alert("발행방법을 선택해주십시오.");
            fm.ck_bnd_isu_methd_cd[0].focus();
            return false;
        }
        var str_iss_mth = '';
        for (i = 0; i < 3; i++) {
            if (fm.ck_bnd_isu_methd_cd[i].checked == true) {
                fm.ck_bnd_isu_methd_cd[i].setValue(1);
            } else {
                fm.ck_bnd_isu_methd_cd[i].setValue(0);
            }
            str_iss_mth += fm.ck_bnd_isu_methd_cd[i].getValue();
        }
    } else {
        //회사채일경우 - 사모채는 선택불가 값='0'
        if (!fm.ck_bnd_isu_methd_cd[0].checked && !fm.ck_bnd_isu_methd_cd[1].checked) {
            alert("발행방법을 선택해주십시오.");
            fm.ck_bnd_isu_methd_cd[0].focus();
            return false;
        }
        var str_iss_mth = '';
        for (i = 0; i < 2; i++) {
            if (fm.ck_bnd_isu_methd_cd[i].checked == true) {
                fm.ck_bnd_isu_methd_cd[i].setValue(1);
            } else {
                fm.ck_bnd_isu_methd_cd[i].setValue(0);
            }
            str_iss_mth += fm.ck_bnd_isu_methd_cd[i].getValue();
        }
        str_iss_mth += 0;
    }
    fm.bnd_isu_methd_cd.setValue(str_iss_mth);


    //발행가액
    if (GetByte(fm.bnd_isu_prc.getValue()) == 0) {
        alert("발행가액을 입력해주십시오.");
        fm.bnd_isu_prc.focus();
        return false;
    }
    //만기상환률
    if (GetByte(fm.exp_redmpt_rto.getValue()) == 0) {
        alert("만기상환률을 입력해주십시오.");
        fm.exp_redmpt_rto.focus();
        return false;
    }


    //국고채권(GB035), 한국은행(AB101), 예금보험공사(AB526) 발행기관의 경우 낙찰금리 입력체크 경고창
    /*if( fm.isur_cd.value == 'GB035' || fm.isur_cd.value == 'AB101' || fm.isur_cd.value == 'AB526' ){
		    if( GetByte(fm.scbd_int.value) == 0) {
		    	if (!confirm("낙찰금리가 입력되지 않았습니다.\n계속 진행하시겠습니까?")) {
			        fm.scbd_int.focus();
			        return false;
		    	}
		    }
	    }*/

    //지방채구분
    if (bnd_mktact_tp_cd == '121' || bnd_mktact_tp_cd == '122') {
        if (GetByte(fm.munibnd_tp_cd.getValue()) == 0) {
            alert("지방채구분을 선택해주십시오.");
            fm.munibnd_tp_cd.focus();
            return false;
        }
    }

    //###################### 이자지급계산월수 #########################
    if (bnd_mktact_tp_cd == '113' || bnd_mktact_tp_cd == '111' || bnd_mktact_tp_cd == '112' || bnd_mktact_tp_cd == '121' || bnd_mktact_tp_cd == '122') {
        if (fm.int_pay_methd_cd[0].checked || fm.int_pay_methd_cd[1].checked) {
            if (fm.int_pay_unit_mms.getValue() == '') {
                alert("이자지급방법이 이표채,복리채인 경우 \n\r이자지급주기를 입력해주십시오.");
                fm.int_pay_unit_mms.focus();
                return false;
            }
            //if (fm.int_pay_calc_mms.value == '') {
            if (fm.cb_int_pay_calc_mms.options[0].selected && fm.int_pay_calc_mms.getValue() == '') {
                alert("이자지급방법이 이표채,복리채인 경우 \n\r이자계산주기를 입력해주십시오.");
                fm.int_pay_calc_mms.focus();
                return false;
            }
        }
    } else {
        if (fm.int_pay_methd_cd[0].checked || fm.int_pay_methd_cd[1].checked || fm.int_pay_methd_cd[6].checked || fm.int_pay_methd_cd[7].checked) {
            if (fm.int_pay_unit_mms.getValue() == '') {
                alert("이자지급방법이 이표채,복리채인 경우 \n\r이자지급주기를 입력해주십시오.");
                fm.int_pay_unit_mms.focus();
                return false;
            }
            if (fm.cb_int_pay_calc_mms.options[0].selected && fm.int_pay_calc_mms.getValue() == '') {
                alert("이자지급방법이 이표채,복리채인 경우 \n\r이자계산주기를 입력해주십시오.");
                fm.int_pay_calc_mms.focus();
                return false;
            }
        }
    }

    //최초이자지급일 계산 - null 이거나 0 이면 계산안함
    //if(GetByte( fm.int_pay_unit_mms.value ) > 0 && fm.int_pay_unit_mms.value != "0"){
    //	getFstIntPayDd(fm.isu_dd.value, fm.redmpt_dd.value, fm.int_pay_unit_mms.value);	
    //}

    //이자지급주기는 이자계산주기보다 크거나 같음
    if (parseInt(fm.int_pay_unit_mms.getValue()) < parseInt(fm.int_pay_calc_mms.getValue())) {
        alert("이자지급주기는 이자계산주기보다 크거나 같아야 합니다.");
        fm.int_pay_unit_mms.focus();
        return;
    }
    if (bnd_mktact_tp_cd == '113' || bnd_mktact_tp_cd == '111' || bnd_mktact_tp_cd == '112' || bnd_mktact_tp_cd == '121' || bnd_mktact_tp_cd == '122') {
        if (fm.int_pay_methd_cd[0].checked) {
            if (GetByte(fm.fst_int_pay_dd.getValue()) == 0) {
                alert("이자지급방법이 이표채인 경우 \n\r최초 이자지급일을 입력해주십시오.");
                fm.fst_int_pay_dd.focus();
                return false;
            } else {
                if (bnd_mktact_tp_cd.substr(2, 1) != '2') {
                    var fstIntPayDdCheck = fm.fst_int_pay_dd_check.getValue();
                    var fstIntPayDd = fm.fst_int_pay_dd.getValue().replace(/-/gi, "");
                    if (fstIntPayDdCheck != fstIntPayDd) {
                        if (!confirm("최초 이자지급일이 '발행일 + 이자지급주기'에 맞지 않습니다.\n그래도 처리하시겠습니까?")) {
                            fm.fst_int_pay_dd.focus();
                            return false;
                        }
                    }
                }
            }
        }
    } else {
        if (fm.int_pay_methd_cd[0].checked || fm.int_pay_methd_cd[6].checked) {
            if (GetByte(fm.fst_int_pay_dd.getValue()) == 0) {
                alert("이자지급방법이 이표채인 경우 \n\r최초 이자지급일을 입력해주십시오.");
                fm.fst_int_pay_dd.focus();
                return false;
            } else {
                if (bnd_mktact_tp_cd.substr(2, 1) != '2') {
                    var fstIntPayDdCheck = fm.fst_int_pay_dd_check.getValue();
                    var fstIntPayDd = fm.fst_int_pay_dd.getValue().replace(/-/gi, "");
                    if (fstIntPayDdCheck != fstIntPayDd) {
                        if (!confirm("최초 이자지급일이 '발행일 + 이자지급주기'에 맞지 않습니다.\n그래도 처리하시겠습니까?")) {
                            fm.fst_int_pay_dd.focus();
                            return false;
                        }
                    }
                }
            }
        }
    }

    //개별상장만 적용
    if (bnd_mktact_tp_cd == '113' || bnd_mktact_tp_cd == '111' || bnd_mktact_tp_cd == '121' || bnd_mktact_tp_cd == '131' || bnd_mktact_tp_cd == '141' || bnd_mktact_tp_cd == '151') {
        //영구채제외	    	
        if (!fm.redmpt_methd_tp_cd[4].checked) {
            //이자지급방법이 고정금리형일 경우 원리금 입력 필수 - 표면이자율 미확정시는 제외
            if (fm.coupn_rt_final_yn[0].checked && (fm.int_pay_methd_cd[0].checked || fm.int_pay_methd_cd[1].checked || fm.int_pay_methd_cd[2].checked || fm.int_pay_methd_cd[4].checked)) {
                if (fm.princint_count.getValue() == '0') {
                    if (fm.int_pay_methd_cd[0].checked) {
                        alert("이자지급방법이 고정금리형-이표채인 경우 \n\r원리금정보를 입력해 주시기 바랍니다.");
                    } else if (fm.int_pay_methd_cd[1].checked) {
                        alert("이자지급방법이 고정금리형-복리채인 경우 \n\r원리금정보를 입력해 주시기 바랍니다.");
                    } else if (fm.int_pay_methd_cd[2].checked) {
                        alert("이자지급방법이 고정금리형-단리채인 경우 \n\r원리금정보를 입력해 주시기 바랍니다.");
                    } else if (fm.int_pay_methd_cd[3].checked) {
                        alert("이자지급방법이 고정금리형-할인채인 경우 \n\r원리금정보를 입력해 주시기 바랍니다.");
                    } else if (fm.int_pay_methd_cd[4].checked) {
                        alert("이자지급방법이 고정금리형-복5단2인 경우 \n\r원리금정보를 입력해 주시기 바랍니다.");
                    } else if (fm.int_pay_methd_cd[5].checked) {
                        alert("이자지급방법이 고정금리형-기타인 경우 \n\r원리금정보를 입력해 주시기 바랍니다.");
                    }
                    scwin.PopUp_rdmp_info(fm);
                    return false;
                }
            }
        }

        /* 변동금리형 이표채 개월수 구분을 합치면서 조건삭제 230224 yako
	    	//이자지급방법이 변동금리형 이표(3개월)일때 이자지급주기 '3' 체크
		    if ( fm.int_pay_methd_cd[6].checked && fm.int_pay_unit_mms.value != '3') {
    			alert("이자지급방법( 변동금리형-이표채(3개월) )과 이자지급주기가 맞지 않습니다.");
    			fm.int_pay_unit_mms.focus();
    			return false;
		    }
	    	//이자지급방법이 변동금리형 이표(6개월)일때 이자지급주기 '6' 체크
		    if ( fm.int_pay_methd_cd[7].checked && fm.int_pay_unit_mms.value != '6') {
		    	alert("이자지급방법( 변동금리형-이표채(6개월) )과 이자지급주기가 맞지 않습니다.");
    			fm.int_pay_unit_mms.focus();
    			return false;
		    }*/
    }

    //###################### 이자지급계산월수 값 setting #########################
    if (fm.cb_int_pay_calc_mms.options[0].selected) {
        fm.int_pay_calc_mms.setValue('');
    } else if (fm.cb_int_pay_calc_mms.options[1].selected) {
        fm.int_pay_calc_mms.setValue(0);
    }

    //###################### 발행조건 값 setting #########################
    /*var str_uosb = '';
    for (i = 0; i < 10; i++) {
        if (fm.ck_uosb[i].checked == true) {
            fm.ck_uosb[i].value = 1;
        } else {
            fm.ck_uosb[i].value = 0;
        }
        str_uosb += fm.ck_uosb[i].value;
    }
    fm.ef_uosb.value = str_uosb;
    */

    if (fm.bnd_sale_tp_cd[0].checked) {
        if (fm.bnd_pre_sale_int_pay_methd_cd.options[0].selected) {
            alert('선매출시 이자지급방법을 선택하십시오.');
            fm.bnd_pre_sale_int_pay_methd_cd.focus();
            return false;
        }
        if (GetByte(fm.sale_dd.getValue()) == 0) {
            alert('선매출시 매출일을 입력하십시오.');
            fm.sale_dd.focus();
            return false;
        }
    }

    //###################### 관련기관 #########################
    if (GetByte(fm.reg_inst_nm.getValue()) == 0) {
        alert("(전자)등록기관을 입력해주십시오.");
        fm.reg_inst_nm.focus();
        return false;
    }

    //임시주석 yakorgy
    if (GetByte(fm.princint_pay_agnt_nm.getValue()) == 0) {
        alert("원리금지급대행기관을 입력해주십시오.");
        fm.princint_pay_agnt_nm.focus();
        return false;
    }

    /*	    if (!fm.cb_crdt_inst1.checked && GetByte(fm.cb_crdt_inst1_grad.value) > 0) {
    	        alert("신용평가등급의 해당 신용평가기관을 선택바랍니다.");
    	        fm.cb_crdt_inst1.focus();
    	        return false;
    	    }

    	    if (!fm.cb_crdt_inst2.checked && GetByte(fm.cb_crdt_inst2_grad.value) > 0) {
    	        alert("신용평가등급의 해당 신용평가기관을 선택바랍니다.");
    	        fm.cb_crdt_inst2.focus();
    	        return false;
    	    }

    	    if (!fm.cb_crdt_inst3.checked && GetByte(fm.cb_crdt_inst3_grad.value) > 0) {
    	        alert("신용평가등급의 해당 신용평가기관을 선택바랍니다.");
    	        fm.cb_crdt_inst3.focus();
    	        return false;
    	    }

    	    if (!fm.cb_crdt_inst4.checked && GetByte(fm.cb_crdt_inst4_grad.value) > 0) {
    	        alert("신용평가등급의 해당 신용평가기관을 선택바랍니다.");
    	        fm.cb_crdt_inst4.focus();
    	        return false;
    	    }*/

    if (bnd_mktact_tp_cd == '113' || bnd_mktact_tp_cd == '111' || bnd_mktact_tp_cd == '121' || bnd_mktact_tp_cd == '131' || bnd_mktact_tp_cd == '141' || bnd_mktact_tp_cd == '151') {
        if (GetByte(fm.udwrt_inst_nm1.getValue()) > 0 && GetByte(fm.udwrt_amt1.getValue()) == 0) {
            alert("인수기관1의 인수금액을 입력바랍니다.");
            fm.udwrt_amt1.focus();
            return false;
        }
        if (GetByte(fm.udwrt_inst_nm1.getValue()) == 0 && GetByte(fm.udwrt_amt1.getValue()) > 0) {
            alert("인수기관1의 인수기관을 선택바랍니다.");
            fm.udwrt_inst_nm1.focus();
            return false;
        }
        if (GetByte(fm.udwrt_inst_nm2.getValue()) > 0 && GetByte(fm.udwrt_amt2.getValue()) == 0) {
            alert("인수기관2의 인수금액을 입력바랍니다.");
            fm.udwrt_amt2.focus();
            return false;
        }
        if (GetByte(fm.udwrt_inst_nm2.getValue()) == 0 && GetByte(fm.udwrt_amt2.getValue()) > 0) {
            alert("인수기관2의 인수기관을 선택바랍니다.");
            fm.udwrt_inst_nm2.focus();
            return false;
        }
        if (GetByte(fm.udwrt_inst_nm3.getValue()) > 0 && GetByte(fm.udwrt_amt3.getValue()) == 0) {
            alert("인수기관3의 인수금액을 입력바랍니다.");
            fm.udwrt_amt3.focus();
            return false;
        }
        if (GetByte(fm.udwrt_inst_nm3.getValue()) == 0 && GetByte(fm.udwrt_amt3.getValue()) > 0) {
            alert("인수기관3의 인수기관을 선택바랍니다.");
            fm.udwrt_inst_nm3.focus();
            return false;
        }
        if (GetByte(fm.udwrt_inst_nm4.getValue()) > 0 && GetByte(fm.udwrt_amt4.getValue()) == 0) {
            alert("인수기관4의 인수금액을 입력바랍니다.");
            fm.udwrt_amt4.focus();
            return false;
        }
        if (GetByte(fm.udwrt_inst_nm4.getValue()) == 0 && GetByte(fm.udwrt_amt4.getValue()) > 0) {
            alert("인수기관4의 인수기관을 선택바랍니다.");
            fm.udwrt_inst_nm4.focus();
            return false;
        }

        //같은 인수기관을 등록했는지 체크
        var isUdwrt_inst_check = false;
        for (var i = 1; i < 5; i++) {
            for (var j = 1; j < 5; j++) {
                if (i != j) {
                    if (eval("fm.udwrt_inst_cd" + i + ".value") != '' && (eval("fm.udwrt_inst_cd" + i + ".value") == eval("fm.udwrt_inst_cd" + j + ".value"))) {
                        isUdwrt_inst_check = true;
                    }
                }
            }
        }
        if (isUdwrt_inst_check) {
            alert("인수기관은 동일한 기관으로 등록할 수 없습니다.");
            fm.udwrt_inst_nm1.focus();
            return false;
        }
    }
    return true;
};






