/**
 * @method
 * @name ReqDataCheckValues
 * @description desc
 * @param {string} fm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ReqDataCheckValues = function(fm) {
    if (GetByte(fm.apct_nm.getValue()) == 0) {
        alert("발행기관의 신청인이름을 입력해주십시오.");
        fm.apct_nm.focus();
        return false;
    }
    if (GetByte(fm.apct_tel_no1.getValue()) == 0) {
        alert("발행기관의 신청인전화번호를 입력해주십시오.");
        fm.apct_tel_no1.focus();
        return false;
    } else if (GetByte(fm.apct_tel_no2.getValue()) == 0) {
        alert("발행기관의 신청인전화번호를 입력해주십시오.");
        fm.apct_tel_no2.focus();
        return false;
    } else if (GetByte(fm.apct_tel_no3.getValue()) == 0) {
