        fm.apct_tel_no3.focus();
        return false;
    }
    if (GetByte(fm.apct_fax_no1.getValue()) == 0) {
        alert("발행기관의 신청인팩스번호를 입력해주십시오.");
        fm.apct_fax_no1.focus();
        return false;
    } else if (GetByte(fm.apct_fax_no2.getValue()) == 0) {
        alert("발행기관의 신청인팩스번호를 입력해주십시오.");
        fm.apct_fax_no2.focus();
        return false;
    } else if (GetByte(fm.apct_fax_no3.getValue()) == 0) {
        alert("발행기관의 신청인팩스번호를 입력해주십시오.");
        fm.apct_fax_no3.focus();
        return false;
    }
    if (GetByte(fm.encryp_apct_email1.getValue()) == 0) {
        alert("발행기관의 신청인 이메일을 입력해주십시오.");
        fm.encryp_apct_email1.focus();
        return false;
    } else if (GetByte(fm.encryp_apct_email2.getValue()) == 0) {
        alert("발행기관의 신청인 이메일을 입력해주십시오.");
        fm.encryp_apct_email2.focus();
        return false;
    } else {
        var email = fm.encryp_apct_email1.getValue() + '@' + fm.encryp_apct_email2.getValue();
        if (!CheckEmail(email)) {
            alert("발행기관의 신청인 이메일이 올바르지 않습니다.");
            fm.encryp_apct_email2.focus();
            return false;
        }
    }

    //휴대폰번호
    if (GetByte(fm.encryp_cellphone_no1.getValue()) == 0) {
        alert("발행기관의 신청인휴대폰번호를 입력해주십시오.");
        fm.encryp_cellphone_no1.focus();
        return false;
    } else if (GetByte(fm.encryp_cellphone_no2.getValue()) == 0) {
        alert("발행기관의 신청인휴대폰번호를 입력해주십시오.");
        fm.encryp_cellphone_no2.focus();
        return false;
    } else if (GetByte(fm.encryp_cellphone_no3.getValue()) == 0) {
        alert("발행기관의 신청인휴대폰번호를 입력해주십시오.");
        fm.encryp_cellphone_no3.focus();
        return false;
    }

    //신청인구분이 발행기관이 아니면 필수로 체크
    if (fm.bnd_apct_tp_cd.getValue() != '1') {
        if (GetByte(fm.rep_majagnt_com_nm.getValue()) == 0) {
            alert("신청기관명을 입력해주십시오.");
            fm.rep_majagnt_com_nm.focus();
            return false;
        }
        if (GetByte(fm.rep_majagnt_com_chrg_nm.getValue()) == 0) {
            alert("신청인이름을 입력해주십시오.");
            fm.rep_majagnt_com_chrg_nm.focus();
            return false;
        }
        if (GetByte(fm.rep_majagnt_com_tel_no1.getValue()) == 0) {
            alert("신청인전화번호를 입력해주십시오.");
            fm.rep_majagnt_com_tel_no1.focus();
            return false;
        } else if (GetByte(fm.rep_majagnt_com_tel_no2.getValue()) == 0) {
            alert("신청인전화번호를 입력해주십시오.");
            fm.rep_majagnt_com_tel_no2.focus();
            return false;
        } else if (GetByte(fm.rep_majagnt_com_tel_no3.getValue()) == 0) {
            alert("신청인전화번호를 입력해주십시오.");
            fm.rep_majagnt_com_tel_no3.focus();
            return false;
        }
        if (GetByte(fm.rep_majagnt_com_fax_no1.getValue()) == 0) {
            alert("신청인팩스번호를 입력해주십시오.");
            fm.rep_majagnt_com_fax_no1.focus();
            return false;
        } else if (GetByte(fm.rep_majagnt_com_fax_no2.getValue()) == 0) {
            alert("신청인팩스번호를 입력해주십시오.");
            fm.rep_majagnt_com_fax_no2.focus();
            return false;
        } else if (GetByte(fm.rep_majagnt_com_fax_no3.getValue()) == 0) {
            alert("신청인팩스번호를 입력해주십시오.");
            fm.rep_majagnt_com_fax_no3.focus();
            return false;
        }
        if (GetByte(fm.encryp_rep_majagnt_com_email1.getValue()) == 0) {
            alert("신청인 이메일을 입력해주십시오.");
            fm.encryp_rep_majagnt_com_email1.focus();
            return false;
        } else if (GetByte(fm.encryp_rep_majagnt_com_email2.getValue()) == 0) {
            alert("신청인 이메일을 입력해주십시오.");
            fm.encryp_rep_majagnt_com_email2.focus();
            return false;
        } else {
            var email = fm.encryp_rep_majagnt_com_email1.getValue() + '@' + fm.encryp_rep_majagnt_com_email2.getValue();
            if (!CheckEmail(email)) {
                alert("신청인 이메일이 올바르지 않습니다.");
                fm.encryp_rep_majagnt_com_email2.focus();
                return false;
            }
        }

        //대표주관회사 휴대폰번호
        if (GetByte(fm.encryp_com_chrg_cellphone_no1.getValue()) == 0) {
            alert("신청인 휴대폰번호를 입력해주십시오.");
            fm.encryp_com_chrg_cellphone_no1.focus();
            return false;
        } else if (GetByte(fm.encryp_com_chrg_cellphone_no2.getValue()) == 0) {
            alert("신청인 휴대폰번호를 입력해주십시오.");
            fm.encryp_com_chrg_cellphone_no2.focus();
            return false;
        } else if (GetByte(fm.encryp_com_chrg_cellphone_no3.getValue()) == 0) {
            alert("신청인 휴대폰번호를 입력해주십시오.");
            fm.encryp_com_chrg_cellphone_no3.focus();
            return false;
        }
    }

    //개인정보수집동의 체크
    if (fm.prn_info_collct_consnt_yn.checked == false) {
        alert("개인정보 수집 및 이용에 동의해 주세요.");
        fm.prn_info_collct_consnt_yn.focus();
        return false;
    }
    return true;
};



