/**
 * @method
 * @name fn_holdy_princ_onchange
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_holdy_princ_onchange = function() {
    var fm = document.SendForm;
    if (fm.bk_holdy_princ_pay_dd_decsn_cd[0].checked || fm.bk_holdy_princ_pay_dd_decsn_cd[2].checked || fm.bk_holdy_princ_pay_dd_decsn_cd[4].checked) {
        fm.bk_holdy_dd_princ_bas_int_cd.setValue("");
        fm.bk_holdy_dd_princ_acrint_rt.setValue("");
        fm.bk_holdy_dd_princ_bas_int_cd.setDisabled(true);
        fm.bk_holdy_dd_princ_acrint_rt.setDisabled(true);
    } else {
        fm.bk_holdy_dd_princ_bas_int_cd.setDisabled(false);
        fm.bk_holdy_dd_princ_acrint_rt.setDisabled(false);
    }
};
