/**
 * @method
 * @name ElbNewLstCheckValues
 * @description desc
 * @param {string} fm desc
 * @param {string} bnd_mktact_tp_cd desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.ElbNewLstCheckValues = function(fm, bnd_mktact_tp_cd) {
    var fm = document.SendForm;
    var _now_time = $("#areaNowTimer").val();
    var _isur_cd = fm.isur_cd.getValue();
    //신청버튼클릭시 시간체크
    if (!applTmCheck(bnd_mktact_tp_cd, _now_time, _isur_cd)) {
        return false;
    }

    //###################### 종목명 ###########################
    if (GetByte(fm.appl_isu_nm.getValue()) == 0) {
        alert("한글종목명을 입력해주십시오.");
        fm.appl_isu_nm.focus();
        return;
    }
    if (GetByte(fm.appl_isu_eng_nm.getValue()) == 0) {
        alert("영문종목명을 선택해주십시오.");
        fm.appl_isu_eng_nm.focus();
        return;
    }

    //###################### 채권분류 #########################
    if (GetByte(fm.isu_amt.getValue()) == 0) {
        alert("발행금액을 입력해주십시오.");
        fm.isu_amt.focus();
        return;
    }
    if (GetByte(fm.list_amt.getValue()) == 0) {
        alert("상장금액을 입력해주십시오.");
        fm.list_amt.focus();
        return;
    }

    //발행금액 >= 상장금액 체크
    if (parseInt(Del_MoneyComma_Value(fm.isu_amt.getValue())) < parseInt(Del_MoneyComma_Value(fm.list_amt.getValue()))) {
        alert("상장금액은 발행금액 보다 작거나 같아야 합니다.");
        fm.list_amt.focus();
        return;
    }
    if (GetByte(fm.isu_dd.getValue()) == 0) {
        alert("발행일을 입력해주십시오.");
        fm.isu_dd.focus();
        return;
    }
    if (GetByte(fm.procs_req_dd.getValue()) == 0) {
        alert("상장희망일을 입력해주십시오.");
        fm.procs_req_dd.focus();
        return;
    }
    if (scwin.fnToday() >= fm.procs_req_dd.getValue().replace("-", "").replace("-", "")) {
        alert("상장희망일은 신청일 익일 이후만 입력가능합니다.");
        fm.procs_req_dd.focus();
        return;
    }

    //상장희망일 - 매매일체크
    Chk_Mkt_Holdy(fm.procs_req_dd);
    if (fm.procs_req_dd_check.getValue() == 'Y') {
        alert("상장희망일은  매매일만 입력가능합니다.");
        fm.procs_req_dd.focus();
        return;
    }
    if (GetByte(fm.redmpt_dd.getValue()) == 0) {
        alert("상환일을 선택해주십시오.");
        fm.redmpt_dd.focus();
        return;
    }

    //발행통화
    if (!fm.curr_tp_cd[0].checked && !fm.curr_tp_cd[1].checked && !fm.curr_tp_cd[2].checked && !fm.curr_tp_cd[3].checked && !fm.curr_tp_cd[4].checked) {
        alert("발행통화를 선택해주십시오.");
        fm.curr_tp_cd[0].focus();
        return;
    }

    //특이채권유형
    if (!fm.nusual_bnd_tp_cd[0].checked && !fm.nusual_bnd_tp_cd[1].checked) {
        alert("특이채권유형을 선택해주십시오.");
        fm.nusual_bnd_tp_cd[0].focus();
        return;
    }

    //권리유형
    if (!fm.rght_tp_cd[0].checked && !fm.rght_tp_cd[1].checked && !fm.rght_tp_cd[2].checked) {
        alert("권리유형을 선택해주십시오.");
        fm.rght_tp_cd[0].focus();
        return;
    }

    //###################### 발행방법 값 setting #########################
    if (!fm.ck_bnd_isu_methd_cd[0].checked && !fm.ck_bnd_isu_methd_cd[1].checked) {
        alert("발행방법을 선택해주십시오.");
        fm.ck_bnd_isu_methd_cd[0].focus();
        return false;
    }
    var str_iss_mth = '';
    for (i = 0; i < 2; i++) {
        if (fm.ck_bnd_isu_methd_cd[i].checked == true) {
            fm.ck_bnd_isu_methd_cd[i].setValue(1);
        } else {
            fm.ck_bnd_isu_methd_cd[i].setValue(0);
        }
        str_iss_mth += fm.ck_bnd_isu_methd_cd[i].getValue();
    }
    str_iss_mth += 0;
    fm.bnd_isu_methd_cd.setValue(str_iss_mth);

    //발행구분
    if (!fm.dom_forn_isu_tp_cd[0].checked && !fm.dom_forn_isu_tp_cd[1].checked) {
        alert("발행구분을 선택해주십시오.");
        fm.dom_forn_isu_tp_cd[0].focus();
        return;
    }
    if (GetByte(fm.nusual_isu_cond_contn.getValue()) > 60) {
        alert("특이발행조건입력시 한글 30자, 영문 60자 미만으로 입력하십시오.");
        fm.nusual_isu_cond_contn.focus();
        return;
    }
    if (GetByte(fm.memo_contn.getValue()) > 200) {
        alert("메모입력시 한글 100자, 영문 200자 미만으로 입력하십시오.");
        fm.ef_memo.focus();
        return;
    }

    //원금보장여부
    if (!fm.princ_grt_yn[0].checked && !fm.princ_grt_yn[1].checked) {
        alert("원금보장여부를 선택해주십시오.");
        fm.princ_grt_yn[0].focus();
        return;
    }
    //원금보장률
    if (GetByte(fm.princ_grt_rt.getValue()) == 0) {
        alert("원금보장률을 입력해주십시오.");
        fm.princ_grt_rt.focus();
        return;
    }
    //기초자산구분
    if (!fm.fnc_uly_tp_cd[0].checked && !fm.fnc_uly_tp_cd[1].checked && !fm.fnc_uly_tp_cd[2].checked && !fm.fnc_uly_tp_cd[3].checked && !fm.fnc_uly_tp_cd[4].checked && !fm.fnc_uly_tp_cd[5].checked && !fm.fnc_uly_tp_cd[6].checked && !fm.fnc_uly_tp_cd[7].checked && !fm.fnc_uly_tp_cd[8].checked && !fm.fnc_uly_tp_cd[9].checked) {
        alert("기초자산구분을 선택해주십시오.");
        fm.fnc_uly_tp_cd[0].focus();
        return;
    }
    //기초자산상세내용
    if (GetByte(fm.uly_contn.getValue()) == 0) {
        alert("기초자산상세내용을 입력해주십시오.");
        fm.uly_contn.focus();
        return;
    }


    //인수기관
    if (GetByte(fm.udwrt_inst_nm1.getValue()) > 0 && GetByte(fm.udwrt_amt1.getValue()) == 0) {
        alert("인수기관1의 인수금액을 입력바랍니다.");
        fm.udwrt_amt1.focus();
        return false;
    }
    if (GetByte(fm.udwrt_inst_nm1.getValue()) == 0 && GetByte(fm.udwrt_amt1.getValue()) > 0) {
        alert("인수기관1의 인수기관을 선택바랍니다.");
        fm.udwrt_inst_nm1.focus();
        return false;
    }
    if (GetByte(fm.udwrt_inst_nm2.getValue()) > 0 && GetByte(fm.udwrt_amt2.getValue()) == 0) {
        alert("인수기관2의 인수금액을 입력바랍니다.");
        fm.udwrt_amt2.focus();
        return false;
    }
    if (GetByte(fm.udwrt_inst_nm2.getValue()) == 0 && GetByte(fm.udwrt_amt2.getValue()) > 0) {
        alert("인수기관2의 인수기관을 선택바랍니다.");
        fm.udwrt_inst_nm2.focus();
        return false;
    }
    if (GetByte(fm.udwrt_inst_nm3.getValue()) > 0 && GetByte(fm.udwrt_amt3.getValue()) == 0) {
        alert("인수기관3의 인수금액을 입력바랍니다.");
        fm.udwrt_amt3.focus();
        return false;
    }
    if (GetByte(fm.udwrt_inst_nm3.getValue()) == 0 && GetByte(fm.udwrt_amt3.getValue()) > 0) {
        alert("인수기관3의 인수기관을 선택바랍니다.");
        fm.udwrt_inst_nm3.focus();
        return false;
    }
    if (GetByte(fm.udwrt_inst_nm4.getValue()) > 0 && GetByte(fm.udwrt_amt4.getValue()) == 0) {
        alert("인수기관4의 인수금액을 입력바랍니다.");
        fm.udwrt_amt4.focus();
        return false;
    }
    if (GetByte(fm.udwrt_inst_nm4.getValue()) == 0 && GetByte(fm.udwrt_amt4.getValue()) > 0) {
        alert("인수기관4의 인수기관을 선택바랍니다.");
        fm.udwrt_inst_nm4.focus();
        return false;
    }

    //같은 인수기관을 등록했는지 체크
    var isUdwrt_inst_check = false;
    for (var i = 1; i < 5; i++) {
        for (var j = 1; j < 5; j++) {
            if (i != j) {
                if (eval("fm.udwrt_inst_cd" + i + ".value") != '' && (eval("fm.udwrt_inst_cd" + i + ".value") == eval("fm.udwrt_inst_cd" + j + ".value"))) {
                    isUdwrt_inst_check = true;
                }
            }
        }
    }
    if (isUdwrt_inst_check) {
        alert("인수기관은 동일한 기관으로 등록할 수 없습니다.");
        fm.udwrt_inst_nm1.focus();
        return false;
    }

    //###################### 이메일수신 동의여부(2011-02-16 최진호) #########################
    if (fm.email_rcv_yn.checked == true) {
        fm.email_rcv_yn.setValue("Y");
    } else {
        fm.email_rcv_yn.setValue("N");
    }

    //신청인사항 필터링
    if (scwin.ReqDataCheckValuesELBDLB(fm)) {
        var bf_file_cnt = parseInt(fm.file_save_cnt.getValue());
        var af_file_cnt = parseInt(fm.file_row_num.getValue()) - bf_file_cnt;

        //파일체크
        var fileYn = 'N';
        if (af_file_cnt > 0) {
            for (var i = 0; i < af_file_cnt; i++) {
                var temp;
                if (af_file_cnt == 1) {
                    temp = fm.attach_file_tp_cd.getValue();
                } else {
                    temp = fm.attach_file_tp_cd[i].getValue();
                }
                if ($("input[name='attach_file_nm[" + i + "]']").val() == "") {
                    alert("파일을 선택하십시오.");
                    $("input[name='attach_file_nm[" + i + "]']").focus();
                    return;
                }
                if (temp == "") {
                    alert("첨부된 파일의 구분을 선택하십시오.");
                    eval("fm.attach_chk" + i + "[0]").focus();
                    return;
                }
            }
        }

        //상장금액 = 인수금액 총계
        if (GetByte(fm.udwrt_amt1.getValue()) > 0 || GetByte(fm.udwrt_amt2.getValue()) > 0 || GetByte(fm.udwrt_amt3.getValue()) > 0 || GetByte(fm.udwrt_amt4.getValue()) > 0 || GetByte(fm.udwrt_amt5.getValue()) > 0) {
            var udwrt1 = fm.udwrt_amt1.getValue();
            var udwrt2 = fm.udwrt_amt2.getValue();
            var udwrt3 = fm.udwrt_amt3.getValue();
            var udwrt4 = fm.udwrt_amt4.getValue();
            var udwrt5 = fm.udwrt_amt5.getValue();
            if (udwrt1 == "") {
                udwrt1 = "0";
            }
            if (udwrt2 == "") {
                udwrt2 = "0";
            }
            if (udwrt3 == "") {
                udwrt3 = "0";
            }
            if (udwrt4 == "") {
                udwrt4 = "0";
            }
            if (udwrt5 == "") {
                udwrt5 = "0";
            }
            var cmt2 = parseInt(Del_MoneyComma_Value(udwrt1)) + parseInt(Del_MoneyComma_Value(udwrt2)) + parseInt(Del_MoneyComma_Value(udwrt3)) + parseInt(Del_MoneyComma_Value(udwrt4)) + parseInt(Del_MoneyComma_Value(udwrt5));
            if (parseInt(Del_MoneyComma_Value(fm.list_amt.getValue())) != cmt2) {
                alert("상장금액과 인수금액 총계가 일치하지 않습니다.");
                fm.udwrt_amt1.focus();
                return;
            }
        }

        //발행방법
        if (bnd_mktact_tp_cd != '141') {
            if (fm.ck_bnd_isu_methd_cd[2].checked) {
                if (!confirm('발행방법이 사모채로 선택되어 있습니다. 계속 진행하시겠습니까?')) {
                    return;
                }
            }
        }

        //발행금액과 상장금액이 1억원 이하 일때 주의팝업
        if (parseInt(Del_MoneyComma_Value(fm.isu_amt.getValue())) < 100000000 && parseInt(Del_MoneyComma_Value(fm.list_amt.getValue())) < 100000000) {
            alert("발행금액과 상장금액이 1억원 이하입니다.");
        } else {
            if (parseInt(Del_MoneyComma_Value(fm.isu_amt.getValue())) < 100000000) {
                alert("발행금액이 1억원 이하입니다.");
            }
            if (parseInt(Del_MoneyComma_Value(fm.list_amt.getValue())) < 100000000) {
                alert("상장금액이 1억원 이하입니다.");
            }
        }

        // 첨부파일 크기 체크(전체 파일사이즈 <= 100)  2024.05.14 by 김효준
        var totFileSize = sumAttachedFilesSize(); // MB
        if (totFileSize > 100) {
            alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
            return;
        }
        if (!confirm("신청하시겠습니까?")) {
            return false;
        }

        //회사채의 경우 내용 보여주기
        /*if(bnd_mktact_tp_cd == '141') {
        	alert("사채납입 증명서는 납입일 오후까지 채권상장시스템\n파일업로드 메뉴에서 업로드 시키거나\n팩스(051-630-2751)로 반드시 보내주시기 바랍니다.");
        }*/

        fm.method.setValue("requestElbListing");
        fm.action = "/listeach/elbListing.do";
        fm.target = "_self";
        fm.submit();
    }
};
